-- Bind delegated documents to the authenticated address and isolate sandbox identities.
CREATE OR REPLACE FUNCTION public.intranet_is_test_mode()
RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public,pg_temp AS $$
 SELECT coalesce((SELECT test_account FROM public.profiles WHERE id=auth.uid()),false);
$$;
CREATE OR REPLACE FUNCTION public.is_intranet_staff(_uid uuid)
RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public,pg_temp AS $$
 SELECT EXISTS(SELECT 1 FROM public.profiles p WHERE p.id=$1 AND p.app_origin='connect'AND p.hr_status='active'AND(public.has_role($1,'admin')OR coalesce(cardinality(p.poles),0)>0));
$$;
-- Legacy policies used Tech and Lifecycle for several departments. Keep those predicates compatible.
CREATE OR REPLACE FUNCTION public.intranet_poles_match(p_poles text[],p_requested text)
RETURNS boolean LANGUAGE sql IMMUTABLE SET search_path=public,pg_temp AS $$
 SELECT coalesce(p_poles,'{}') && CASE p_requested
 WHEN 'tech' THEN ARRAY['tech','product','data','security']
 WHEN 'lifecycle' THEN ARRAY['lifecycle','marketplace','support']
 WHEN 'risk' THEN ARRAY['risk','security']
 WHEN 'product' THEN ARRAY['product','tech']
 WHEN 'data' THEN ARRAY['data','tech']
 WHEN 'security' THEN ARRAY['security','risk','tech']
 WHEN 'marketplace' THEN ARRAY['marketplace','lifecycle']
 WHEN 'support' THEN ARRAY['support','lifecycle'] ELSE ARRAY[p_requested] END;
$$;
CREATE OR REPLACE FUNCTION public.has_pole(_user_id uuid,_pole text)
RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public,pg_temp AS $$
 SELECT EXISTS(SELECT 1 FROM public.profiles p WHERE p.id=$1 AND public.is_intranet_staff($1)AND NOT coalesce(p.test_account,false)AND public.intranet_poles_match(p.poles::text[],$2));
$$;
CREATE OR REPLACE FUNCTION public.has_any_pole(_user_id uuid,_poles text[])
RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public,pg_temp AS $$
 SELECT EXISTS(SELECT 1 FROM unnest(coalesce($2,'{}'))pole WHERE public.has_pole($1,pole));
$$;
CREATE OR REPLACE FUNCTION public.is_leadership(_user_id uuid)
RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public,pg_temp AS $$
 SELECT public.is_intranet_staff($1)AND NOT coalesce((SELECT test_account FROM public.profiles WHERE id=$1),false)
 AND(public.has_role($1,'admin')OR public.has_role($1,'executive')OR public.has_pole($1,'direction'));
$$;
CREATE OR REPLACE FUNCTION public.can_access_rh_profiles(_uid uuid)
RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public,pg_temp AS $$
 SELECT public.is_leadership($1)OR public.has_pole($1,'rh');
$$;
CREATE OR REPLACE FUNCTION public.my_poles()
RETURNS text[] LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public,pg_temp AS $$
 SELECT CASE WHEN public.is_intranet_staff(auth.uid())AND NOT public.intranet_is_test_mode()THEN coalesce((SELECT poles::text[]FROM public.profiles WHERE id=auth.uid()),'{}')ELSE '{}'::text[]END;
$$;
CREATE OR REPLACE FUNCTION public.guard_profile_authorization_fields()
RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public,pg_temp AS $$
DECLARE actor uuid:=auth.uid();field text;changed boolean:=false;
BEGIN
 FOREACH field IN ARRAY ARRAY['id','email','app_origin','position','position_key','poles','seniority','subsidiary','work_mode','hr_status','collaborator_type','manager_id','test_account']LOOP
 IF to_jsonb(NEW)->field IS DISTINCT FROM to_jsonb(OLD)->field THEN changed:=true;EXIT;END IF;END LOOP;
 IF NOT changed THEN RETURN NEW;END IF;
 IF auth.role()='service_role'THEN RETURN NEW;END IF;
 IF actor IS NULL AND coalesce(auth.role(),'')NOT IN ('anon','authenticated')AND EXISTS(SELECT 1 FROM pg_roles WHERE rolname=session_user AND rolsuper)THEN RETURN NEW;END IF;
 IF actor IS NULL OR public.intranet_is_test_mode()OR NOT public.is_intranet_staff(actor)THEN RAISE EXCEPTION 'profile_authorization_fields_forbidden' USING ERRCODE='42501';END IF;
 IF public.has_role(actor,'admin')THEN RETURN NEW;END IF;
 IF OLD.id<>actor AND public.can_access_rh_profiles(actor)THEN RETURN NEW;END IF;
 RAISE EXCEPTION 'profile_authorization_fields_forbidden' USING ERRCODE='42501';
END;
$$;
DROP TRIGGER IF EXISTS guard_profile_authorization_fields ON public.profiles;
CREATE TRIGGER guard_profile_authorization_fields BEFORE UPDATE ON public.profiles FOR EACH ROW EXECUTE FUNCTION public.guard_profile_authorization_fields();
CREATE OR REPLACE FUNCTION public.can_hr_publication_action(p_action text)
RETURNS boolean LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=public,pg_temp AS $$
DECLARE actor uuid:=auth.uid(); saved_count integer; saved_allow boolean; level text;
  in_scope boolean; has_active boolean; only_read_only boolean; legacy_role text;
BEGIN
  IF public.intranet_is_test_mode() THEN RETURN false;END IF;
  IF actor IS NULL OR p_action IS NULL OR p_action NOT IN ('read','create','update','publish')
      OR NOT coalesce(public.is_intranet_staff(actor),false) THEN RETURN false; END IF;
  IF public.has_role(actor,'admin') THEN RETURN true; END IF;
  IF NOT EXISTS(SELECT 1 FROM public.access_assignments WHERE employee_id=actor) THEN
    SELECT public.legacy_hr_publication_role(p.position::text,p.poles::text[]) INTO legacy_role FROM public.profiles p WHERE p.id=actor;
    IF legacy_role IS NOT NULL AND EXISTS(SELECT 1 FROM public.access_roles WHERE role_key=legacy_role)
      AND NOT EXISTS(SELECT 1 FROM public.access_roles WHERE role_key=legacy_role AND status='active') THEN RETURN false; END IF;
  END IF;
  SELECT count(*),coalesce(bool_or(ap.allowed AND ac.action_key=p_action),false)
    INTO saved_count,saved_allow
  FROM public.access_roles ar
  LEFT JOIN public.access_assignments aa ON aa.role_id=ar.id AND aa.employee_id=actor AND aa.status='active'
    AND (aa.starts_at IS NULL OR aa.starts_at<=now()) AND (aa.ends_at IS NULL OR aa.ends_at>=now())
  JOIN public.access_permissions ap ON ap.role_id=ar.id
  JOIN public.access_interfaces ai ON ai.id=ap.interface_id AND ai.interface_key='rh.publications' AND ai.status='active'
  JOIN public.access_actions ac ON ac.id=ap.action_id
  WHERE ar.status='active' AND (aa.employee_id IS NOT NULL OR ar.role_key=legacy_role);
  -- A saved page grants only its explicitly allowed actions, including explicit denials.
  IF saved_count>0 THEN RETURN saved_allow; END IF;
  SELECT count(*)>0,coalesce(bool_and(ar.read_only),false) INTO has_active,only_read_only
  FROM public.access_roles ar
  LEFT JOIN public.access_assignments aa ON aa.role_id=ar.id AND aa.employee_id=actor AND aa.status='active'
    AND (aa.starts_at IS NULL OR aa.starts_at<=now()) AND (aa.ends_at IS NULL OR aa.ends_at>=now())
  WHERE ar.status='active' AND (aa.employee_id IS NOT NULL OR ar.role_key=legacy_role);
  IF NOT has_active AND EXISTS(SELECT 1 FROM public.access_assignments WHERE employee_id=actor) THEN RETURN false; END IF;
  SELECT coalesce(p.seniority::text,'junior'),coalesce('rh'=ANY(p.poles),false)
    INTO level,in_scope FROM public.profiles p WHERE p.id=actor;
  IF public.is_leadership(actor) THEN level:='executive'; in_scope:=true; END IF;
  IF NOT coalesce(in_scope,false) THEN RETURN false; END IF;
  IF p_action='read' THEN RETURN true; END IF;
  IF only_read_only THEN RETURN false; END IF;
  IF p_action IN ('create','update') THEN RETURN level IN ('mid','senior','lead','executive'); END IF;
  RETURN level IN ('lead','executive');
END;
$$;
CREATE OR REPLACE FUNCTION public.handle_new_user()
RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public,pg_temp AS $$
DECLARE claimed_request uuid; request public.hr_employee_requests%ROWTYPE;
BEGIN
  IF coalesce(NEW.raw_user_meta_data->>'app_origin','')='connect'
      AND NEW.invited_at IS NULL AND NEW.email_confirmed_at IS NULL THEN
    -- Lock in the same order as reservation so a concurrent rejection cannot
    -- authorize creation from an obsolete validated request.
    SELECT * INTO request FROM public.hr_employee_requests
    WHERE id::text=NEW.raw_user_meta_data->>'hr_onboarding_request_id' FOR UPDATE;
    IF NOT FOUND OR request.request_kind IS DISTINCT FROM 'onboarding'
        OR request.status IS DISTINCT FROM 'hr_validated' OR request.hr_validated_by IS NULL
        OR request.created_user_id IS NOT NULL THEN
      RAISE EXCEPTION 'hr_invitation_request_not_ready' USING ERRCODE='42501';
    END IF;
    UPDATE public.hr_onboarding_invitation_claims claim
    SET consumed_user_id=NEW.id,consumed_at=clock_timestamp()
    WHERE claim.nonce::text=NEW.raw_user_meta_data->>'hr_onboarding_attempt_nonce'
      AND claim.request_id=request.id
      AND claim.email=lower(btrim(NEW.email))
      AND claim.email=lower(btrim(coalesce(request.work_email,request.personal_email,'')))
      AND claim.expires_at>clock_timestamp() AND claim.consumed_at IS NULL
      AND request.request_kind='onboarding' AND request.status='hr_validated'
      AND request.hr_validated_by IS NOT NULL AND request.created_user_id IS NULL
    RETURNING claim.request_id INTO claimed_request;
    IF claimed_request IS NULL THEN
      RAISE EXCEPTION 'Inscription autonome désactivée : les comptes intranet sont créés par les RH.' USING ERRCODE='42501';
    END IF;
  END IF;
  INSERT INTO public.profiles(id,email,first_name,last_name,app_origin,test_account)
  VALUES(NEW.id,NEW.email,coalesce(NEW.raw_user_meta_data->>'first_name','New'),coalesce(NEW.raw_user_meta_data->>'last_name','User'),CASE WHEN NEW.raw_user_meta_data->>'app_origin'='connect' THEN 'connect' ELSE 'bos' END,coalesce(NEW.raw_user_meta_data->>'test_account','false')='true');
  INSERT INTO public.user_roles(user_id,role) VALUES(NEW.id,'viewer');
  RETURN NEW;
END;
$$;
