CREATE TABLE public.intranet_test_identity_events(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),actor_id uuid NOT NULL,target_id uuid NOT NULL,role_key text NOT NULL,kind text NOT NULL,created_at timestamptz NOT NULL DEFAULT now());
ALTER TABLE public.intranet_test_identity_events ENABLE ROW LEVEL SECURITY;
GRANT ALL ON public.intranet_test_identity_events TO service_role;
CREATE OR REPLACE FUNCTION public.configure_intranet_test_identity(p_actor uuid,p_target uuid,p_role text)
RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public,pg_temp AS $$
DECLARE spec public.intranet_test_role_specs%ROWTYPE;target public.profiles%ROWTYPE;planned public.profiles%ROWTYPE;assigned_role uuid;keep_assignment uuid;
BEGIN
 IF auth.role()IS DISTINCT FROM 'service_role'OR NOT public.is_intranet_staff(p_actor)OR NOT public.has_role(p_actor,'admin')OR coalesce((SELECT test_account FROM public.profiles WHERE id=p_actor),true)THEN RAISE EXCEPTION 'test_identity_operator_forbidden' USING ERRCODE='42501';END IF;
 SELECT *INTO spec FROM public.intranet_test_role_specs WHERE role_key=p_role;
 IF NOT FOUND THEN RAISE EXCEPTION 'test_identity_role_unknown' USING ERRCODE='22023';END IF;
 SELECT id INTO assigned_role FROM public.access_roles WHERE role_key=p_role AND status='active';
 IF assigned_role IS NULL THEN RAISE EXCEPTION 'test_identity_role_inactive' USING ERRCODE='42501';END IF;
 PERFORM pg_advisory_xact_lock(hashtextextended('test-identity:'||p_target::text,0));
 SELECT *INTO target FROM public.profiles WHERE id=p_target FOR UPDATE;
 IF NOT FOUND OR NOT coalesce(target.test_account,false)OR NOT EXISTS(SELECT 1 FROM auth.users u WHERE u.id=p_target AND lower(u.email)=spec.email AND u.email_confirmed_at IS NOT NULL AND u.raw_user_meta_data->>'test_account'='true'AND u.raw_user_meta_data->>'job_role'=p_role)THEN RAISE EXCEPTION 'test_identity_target_forbidden' USING ERRCODE='42501';END IF;
 planned:=jsonb_populate_record(NULL::public.profiles,jsonb_build_object('position',spec.position,'poles',spec.poles,'seniority',spec.seniority));
 UPDATE public.profiles SET email=spec.email,first_name=spec.label,last_name='(test)',position=planned.position,position_key=spec.position,poles=planned.poles,seniority=planned.seniority,app_origin='connect',test_account=true WHERE id=p_target;
 SELECT id INTO keep_assignment FROM public.access_assignments WHERE employee_id=p_target AND role_id=assigned_role AND status='active'AND starts_at IS NULL AND ends_at IS NULL ORDER BY id LIMIT 1;
 UPDATE public.access_assignments SET status='revoked'WHERE employee_id=p_target AND status='active'AND(keep_assignment IS NULL OR id<>keep_assignment);
 IF keep_assignment IS NULL THEN INSERT INTO public.access_assignments(employee_id,role_id,status,assigned_by)VALUES(p_target,assigned_role,'active',p_actor);END IF;
 INSERT INTO public.intranet_test_identity_events(actor_id,target_id,role_key,kind)VALUES(p_actor,p_target,p_role,'configured');
END;
$$;
REVOKE ALL ON FUNCTION public.configure_intranet_test_identity(uuid,uuid,text)FROM PUBLIC,anon,authenticated;
GRANT EXECUTE ON FUNCTION public.configure_intranet_test_identity(uuid,uuid,text)TO service_role;
-- All public data tables receive a sandbox boundary. Catalogues carry no personal dataset.
DO $$DECLARE t record;condition text;BEGIN
 FOR t IN SELECT c.relname AS name,c.oid FROM pg_class c JOIN pg_namespace n ON n.oid=c.relnamespace WHERE n.nspname='public'AND c.relkind IN ('r','p')LOOP
 IF t.name IN ('profiles','notifications','access_roles','access_actions','access_interfaces','access_permissions','access_role_scopes','access_scopes','access_portfolio_types','permission_settings','rh_position_catalog','intranet_modules','intranet_business_tables',
 'intranet_record_events','work_task_comments','work_task_history','intranet_document_events','intranet_ethics_events','intranet_outbox_events','intranet_email_dispatch','intranet_document_jobs','intranet_share_requests')THEN CONTINUE;END IF;
 IF EXISTS(SELECT 1 FROM pg_attribute WHERE attrelid=t.oid AND attname='test_account'AND atttypid='boolean'::regtype AND NOT attisdropped)THEN
 condition:='NOT public.is_intranet_actor()OR(public.can_intranet_action(''app.dashboard'',''read'')AND coalesce(test_account,false)=public.intranet_is_test_mode())';
 ELSE condition:='NOT public.intranet_is_test_mode()';END IF;
 EXECUTE format('ALTER TABLE public.%I ENABLE ROW LEVEL SECURITY',t.name);
 EXECUTE format('DROP POLICY IF EXISTS intranet_test_environment ON public.%I',t.name);
 EXECUTE format('CREATE POLICY intranet_test_environment ON public.%I AS RESTRICTIVE FOR ALL TO authenticated USING(%s)WITH CHECK(%s)',t.name,condition,condition);
 END LOOP;
 -- Test accounts may inspect the role catalogue but cannot alter identities or authorizations.
 FOR t IN SELECT c.relname AS name FROM pg_class c JOIN pg_namespace n ON n.oid=c.relnamespace WHERE n.nspname='public'AND c.relkind IN ('r','p')AND(c.relname LIKE 'access_%'OR c.relname IN ('user_roles','admin_roles','admin_permissions','admin_role_permissions','admin_user_roles','admin_user_permissions','permission_settings','rh_position_catalog'))LOOP
 EXECUTE format('ALTER TABLE public.%I ENABLE ROW LEVEL SECURITY',t.name);
 FOREACH condition IN ARRAY ARRAY['INSERT','UPDATE','DELETE']LOOP
 EXECUTE format('DROP POLICY IF EXISTS %I ON public.%I','intranet_authority_'||lower(condition),t.name);
 IF condition='INSERT'THEN EXECUTE format('CREATE POLICY intranet_authority_insert ON public.%I AS RESTRICTIVE FOR INSERT TO authenticated WITH CHECK(NOT public.intranet_is_test_mode()AND public.can_intranet_action(''app.dashboard'',''read''))',t.name);
 ELSIF condition='UPDATE'THEN EXECUTE format('CREATE POLICY intranet_authority_update ON public.%I AS RESTRICTIVE FOR UPDATE TO authenticated USING(NOT public.intranet_is_test_mode()AND public.can_intranet_action(''app.dashboard'',''read''))WITH CHECK(NOT public.intranet_is_test_mode()AND public.can_intranet_action(''app.dashboard'',''read''))',t.name);
 ELSE EXECUTE format('CREATE POLICY intranet_authority_delete ON public.%I AS RESTRICTIVE FOR DELETE TO authenticated USING(NOT public.intranet_is_test_mode()AND public.can_intranet_action(''app.dashboard'',''read''))',t.name);END IF;
 END LOOP;END LOOP;
END $$;
ALTER TABLE public.profiles ENABLE ROW LEVEL SECURITY;
CREATE POLICY intranet_profile_environment ON public.profiles AS RESTRICTIVE FOR SELECT TO authenticated USING(id=auth.uid()OR(NOT public.intranet_is_test_mode()AND public.has_role(auth.uid(),'admin'))OR coalesce(test_account,false)=public.intranet_is_test_mode());
CREATE POLICY intranet_no_profile_insert ON public.profiles AS RESTRICTIVE FOR INSERT TO authenticated WITH CHECK(false);
CREATE POLICY intranet_no_profile_delete ON public.profiles AS RESTRICTIVE FOR DELETE TO authenticated USING(false);
CREATE POLICY intranet_profile_update_environment ON public.profiles AS RESTRICTIVE FOR UPDATE TO authenticated USING(coalesce(test_account,false)=public.intranet_is_test_mode()OR(NOT public.intranet_is_test_mode()AND public.has_role(auth.uid(),'admin')))WITH CHECK(coalesce(test_account,false)=public.intranet_is_test_mode()OR(NOT public.intranet_is_test_mode()AND public.has_role(auth.uid(),'admin')));
ALTER TABLE public.notifications ENABLE ROW LEVEL SECURITY;
CREATE POLICY intranet_test_notifications ON public.notifications AS RESTRICTIVE FOR ALL TO authenticated USING(NOT public.intranet_is_test_mode()OR user_id=auth.uid())WITH CHECK(NOT public.intranet_is_test_mode()OR user_id=auth.uid());
REVOKE ALL ON FUNCTION public.intranet_is_test_mode(),public.intranet_poles_match(text[],text),public.guard_profile_authorization_fields()FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.intranet_is_test_mode()TO authenticated,service_role;
NOTIFY pgrst,'reload schema';
